import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"GeoVLA: Empowering 3D Representations in Vision-Language-Action Models","description":"","frontmatter":{"title":"GeoVLA: Empowering 3D Representations in Vision-Language-Action Models","arxiv":"2508.09071","date":"2025-08-12","authors":"Lin Sun, Bin Xie, Yingfei Liu, Hao Shi, Tiancai Wang, Jiale Cao","categories":"cs.RO","topics":"3D 表征, VLA, 点云编码器","outline":[2,2]},"headers":[],"relativePath":"papers/2508.09071.md","filePath":"papers/2508.09071.md","lastUpdated":null}'),l={name:"papers/2508.09071.md"};function e(m,s,i,r,c,g){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="geovla-empowering-3d-representations-in-vision-language-action-models" tabindex="-1">GeoVLA: Empowering 3D Representations in Vision-Language-Action Models <a class="header-anchor" href="#geovla-empowering-3d-representations-in-vision-language-action-models" aria-label="Permalink to &quot;GeoVLA: Empowering 3D Representations in Vision-Language-Action Models&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2508.09071" target="_blank" rel="noreferrer">2508.09071</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-08-12</td></tr><tr><td><strong>作者</strong></td><td>Lin Sun, Bin Xie, Yingfei Liu, Hao Shi, Tiancai Wang, Jiale Cao</td></tr><tr><td><strong>分类</strong></td><td>cs.RO</td></tr><tr><td><strong>一句话</strong></td><td>不动 VLM，把深度图转成以末端执行器为原点的点云、用 RoPE 引导的编码器只取「末端锚点 token」，再送进静态路由 MoE 扩散动作头与视觉-语言特征融合。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>本文依据 arXiv 页面给出的 HTML 版本 <strong>v2</strong>（v1 提交于 2025-08-12，v2 修订于 2025-08-13）撰写。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>现在的 VLA 几乎全靠 2D RGB。这在桌面抓放上够用，但一旦部署条件变了——相机被挪了 30 度、目标篮子换到另一层高度、物体尺寸变大一圈——策略就开始失手。原因很直接：2D 策略学到的是「像素长这样时该怎么动」，而深度、尺度、视角这三件事恰好是像素外观最不稳定的部分。</p><p>把 3D 信息接进 VLA 有两条已有路线，各有各的代价。一条是改 VLM 本身（LLaVA-3D、SpatialVLA、3D-VLA），把 3D 位置编码塞进视觉 token——代价是打断视觉编码器与 LLM 之间已经对齐好的表示，要修复就得再来一轮大规模 3D 具身指令微调。另一条是改动作头（PointVLA），先训 2D-VLA，再冻结动作专家、用零初始化的 ControlNet 式模块注入点云——冻结确实保住了原有能力，但也让模型没法真正适应这个新模态。</p><p>本文要回答的问题是：<strong>能不能端到端地把 3D 接进来，既不破坏 VLM 的预训练对齐，也不把点云分支锁死在旁路里？</strong></p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>动作表示这条线</strong>：RT-2、OpenVLA 把动作离散成 token 自回归生成，兼容 VLM 架构但精度粗；π₀、RDT-1B、CogACT 改用扩散或流匹配直接参数化连续动作块，轨迹建模明显更准。GeoVLA 站在后者一侧。</p><p><strong>3D 注入 VLM 这条线</strong>：SpatialVLA 用点云导出的空间位置嵌入去装配视觉 token，3D-VLA/3D-CAVLA 直接把 3D 特征当 embedding 喂 VLM。论文的批评是精确的——这类改动破坏了视觉表示与 LLM 的对齐，恢复对齐需要额外的具身指令微调阶段，成本高。LLARVA 甚至因此退回到用 2D 视觉轨迹这种抽象表示来保持兼容性。这里的关键洞察是：<strong>问题不在于 3D 没用，而在于注入位置选错了。</strong></p><p><strong>3D 注入动作头这条线</strong>：PointVLA 的零初始化注入器不需要重训动作专家，但作者指出这同时意味着模型无法对新模态做出适应。这是一个真实的两难：不冻结怕破坏，冻结又学不动。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>在本文之前已经确立的三件事：（i）VLM 的视觉-语言对齐是靠海量图文数据训出来的，任何改动视觉 token 几何编码的操作都会打破它；（ii）扩散/流匹配动作专家本身就是从零训的，破坏对齐这个顾虑在它这里不存在；（iii）DP3 一类工作已经证明，机器人操作用的点云不需要大型 3D 骨干，轻量编码器就够。</p><p>顺着这三条，最保守也最合理的设计是：<strong>把 3D 完全放在 VLM 之外的并行分支，只在动作头里汇合</strong>。这样 VLM 原封不动，点云分支可以从零自由训练。</p><p>但立刻会遇到两个具体障碍。第一，RGB-D 相机的深度本身噪声大，直接把整片点云当 token 序列既贵又脏。这里需要一个「压缩到什么」的选择——而操作任务的几何本质是<strong>末端执行器与周围物体的相对关系</strong>，所以把点云表达在末端执行器坐标系（末端在原点）并只取原点处那个 token 作为输出，是一个信息论上合理的瓶颈。第二，VLM 分支是预训练的、点云分支是随机初始化的，两者放进同一个 MoE 动作头时，动态路由会天然偏向已经收敛的那一支。这个现象作者明确报告了，解法也很直接：用<strong>静态路由</strong>，靠训练时随机丢模态来强制两个专家都被用上。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>3D 信息不必进 VLM，只要进动作头就够——把它塞进 VLM 会打断已经对齐好的视觉-语言表示，得不偿失。而对操作来说，点云里真正有用的是「末端执行器周围有什么、离多远」，所以把点云转到末端坐标系、只留下原点那个 token，就能用极小的带宽携带关键几何。剩下的麻烦是预训练分支会压过随机初始化分支，把动态路由换成按模态丢弃驱动的静态路由即可。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以真机任务「Put Basketball」（把球投进篮筐）为例：</p><ol><li><strong>2D 分支</strong>：RGB 图像 + 指令送进 Prismatic-7B（用 OpenVLA 在 Open X-Embodiment 上的预训练权重初始化），得到融合的视觉-语言特征 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0993em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0993em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.2222em;">V</span><span class="mord mathnormal mtight">L</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>。这一支完全不改。</li><li><strong>3D 分支（PEN）</strong>：RealSense 深度图按相机内外参反投影成点云 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span></span></span></span>，并<strong>变换到末端执行器坐标系</strong>（当前末端位于原点）。双路结构——几何路用多层大核卷积 + 局部池化得到 patch 级 token <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0993em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0993em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">p</span><span class="mord mathnormal mtight">c</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8413em;"></span><span class="mord"><span class="mord mathbb">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span><span class="mbin mtight">×</span><span class="mord mathnormal mtight" style="margin-right:0.0715em;">C</span></span></span></span></span></span></span></span></span></span></span></span>，位置路把点云下采样到同样规模后用 RoPE 生成位置引导。Transformer 块在 RoPE 引导下让 token 交互，最后<strong>只取坐标原点对应的那个 anchor token</strong> 作为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0993em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0993em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">P</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>。</li><li><strong>动作头（3DAE）</strong>：DiT 架构。噪声动作块与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord"><span class="mord mathcal" style="margin-right:0.0993em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0993em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.2222em;">V</span><span class="mord mathnormal mtight">L</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">;</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0993em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0993em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">P</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">]</span></span></span></span> 拼接后交互，预测噪声。FFN 换成 MoE，路由是<strong>静态</strong>的——训练时每次迭代随机丢一个模态，产生三种输入配置（仅视觉-语言 / 语言+几何 / 全模态），专家的激活由输入模态的存在与否确定性决定。</li><li><strong>推理</strong>：DDIM 采样，动作块长度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">16</span></span></span></span>，每个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">Δ</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">Δ</span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">Δ</span><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">Δ</span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">Δ</span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">Δ</span><span class="mord mathnormal" style="margin-right:0.0556em;">γ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mclose">)</span></span></span></span>。</li><li><strong>训练规模</strong>：8×A100，总 batch 256，AdamW 恒定 lr <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">5</span></span></span></span></span></span></span></span></span></span></span></span>，约 20000 步 / 20 小时；不用任何数据增强。</li></ol><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文没有新的形式化结果，公式都是标准记号（式 1–3 只是把策略从 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">L</span><span class="mclose">)</span></span></span></span> 扩成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">L</span><span class="mclose">)</span></span></span></span>，扩散部分用的是常规 DDPM 训练 + DDIM 采样）。真正有内容的是 PEN 的坐标系选择，值得把它的几何含义讲清楚。</p><p>设相机到机器人基座的外参为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">c</span><span class="mord mathnormal mtight">b</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mopen">(</span><span class="mord">3</span><span class="mclose">)</span></span></span></span>，当前末端位姿为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">b</span><span class="mord mathnormal mtight">e</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mopen">(</span><span class="mord">3</span><span class="mclose">)</span></span></span></span>。深度图反投影得到相机系点云 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">c</span></span></span></span></span></span></span></span></span></span></span></span>，PEN 使用的是</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7144em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7144em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">e</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1141em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">b</span><span class="mord mathnormal mtight">e</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose"><span class="mclose">)</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">1</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">c</span><span class="mord mathnormal mtight">b</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7144em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">c</span></span></span></span></span></span></span></span></span></span></span></span></span></p><p>这个变换的作用是把<strong>当前末端位姿从输入里消掉</strong>：无论机械臂当前在哪、相机架在哪，同一个「末端与物体的相对构型」都会映射到同一片 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">e</span></span></span></span></span></span></span></span></span></span></span>。而动作恰好也是相对量 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">Δ</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">Δ</span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">Δ</span><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mclose">)</span></span></span></span>。于是 3D 分支上的输入-输出关系天然对整体刚体变换等变——这就是视角变化实验（表 7，45° 时 GeoVLA 70 vs CogACT 0）背后的机制，也是全文最有力的设计论证。</p><p>代价同样清楚：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">e</span></span></span></span></span></span></span></span></span></span></span> 依赖 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">c</span><span class="mord mathnormal mtight">b</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">b</span><span class="mord mathnormal mtight">e</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 两个外部量。相机标定误差与末端位姿误差会直接进入点云的坐标，且不会被任何机制补偿——见 §9。</p><p>选 anchor token 的做法也可以这样理解：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">e</span></span></span></span></span></span></span></span></span></span></span> 的原点恒为末端，因此原点邻域的 token 就是「末端周围有什么」的局部描述子，通过 Transformer 与 RoPE 与全场交互后，它携带的是以末端为参照系的场景摘要。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>能不能在标准基准上站住？</strong> LIBERO 五套件：GeoVLA 平均 97.7%（Spatial 98.4 / Object 99.0 / Goal 96.6 / Long 96.6 / LIBERO-90 97.7），高于 OpenVLA-OFT 95.3、CogACT 93.2、π₀ 94.2。要注意口径：π₀ 与 OpenVLA-OFT 用了额外的本体感受状态或腕部相机（表中标 *），而 GeoVLA 只用主相机 + 对应深度。ManiSkill2 五任务均值 77%（CogACT 69、Dita 66），优势最大的是最难的 PickClutterYCB（45 vs Dita 36）。</p><p><strong>每个组件值多少？</strong>（LIBERO 平均）点云编码器：MLP 95.8、PointNet 95.2、PEN 97.7。anchor 选择：Max 96.3、Mean 95.9、末端 token 97.7。位置编码：1D 可学习 95.4、RoPE 97.7。动作头：无 MoE 96.0、动态路由 97.3、静态路由 97.7。方向都对，但幅度都在 1.5–2.5 点，且<strong>逐项并非全胜</strong>——MLP 编码器在 Goal 上 97.8 反而高于 PEN 的 96.6，动态路由在 Goal 上 98.4 高于静态的 96.6。静态路由相对动态路由只差 0.4 点。</p><p><strong>真机与部署鲁棒性</strong>（WidowX-250s + RealSense-435i，第三人称约 0.8m，每任务 10 次试验）。域内 8 个任务均值：GeoVLA 86.3、CogACT 76.3、π₀ 57.5、OpenVLA 20.0。所谓「超过 π₀ 28.8%」是绝对点差。</p><p>四组变化实验才是核心论证：</p><ul><li><strong>篮筐高度</strong>（训练只在第 5 层）：GeoVLA 在 L2/L1/Base/H1 上 50/70/90/60，CogACT 20/30/60/20，π₀ 50/40/50/20。GeoVLA 在 Base 上优势最大，最难的 L2 与 π₀ <strong>持平</strong>（都是 50）。</li><li><strong>玩偶尺寸</strong>：GeoVLA 70/70/80/80，CogACT 70/70/40/50，π₀ 10/50/20/0。变大时优势明显，S1 档与 CogACT 持平。</li><li><strong>相机视角</strong>：Base/15°/30°/45° 上 GeoVLA 90/90/80/70，CogACT 80/60/40/<strong>0</strong>，π₀ 50/50/40/30。这是全文最干净的一组，与 §6 的等变性论证完全吻合。</li><li><strong>撤掉海绵垫</strong>（胡萝卜位置变低）：GeoVLA 100→<strong>50</strong>，CogACT 100→10，π₀ 100→<strong>60</strong>。正文写「我们的几何感知 GeoVLA 始终能更稳定成功抓取」，但<strong>表 8 里 π₀ 的 60 高于 GeoVLA 的 50</strong>，该表述不成立，需如实指出。</li></ul><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句版</strong>：GeoVLA 把 3D 完全放在 VLM 之外——深度图转成以末端执行器为原点的点云，由 PEN 编码后只输出一个「末端 anchor token」，与视觉-语言特征一起送进静态路由 MoE 的扩散动作头。末端坐标系的选择使 3D 分支对整体刚体变换近似等变，这是视角鲁棒性（45° 时 70 vs CogACT 0）的机制来源。静态路由是为了防止随机初始化的点云专家被预训练的 VLM 专家压过去。LIBERO 平均 97.7%、ManiSkill2 77%、真机 8 任务 86.3%，均为表内最好。但组件消融幅度只有 1.5–2.5 点且逐项非全胜，撤海绵垫一项 GeoVLA 反而输给 π₀。</p><p><strong>3 句版</strong>：3D 不进 VLM、只进动作头，且把点云转到末端坐标系再压成单个 anchor token。这使策略对相机视角与目标高度变化明显更稳。绝对性能领先，但单项消融与个别变化实验并不一致支持。</p><p><strong>1 句版</strong>：用末端执行器坐标系下的一个点云 token，给 2D VLA 补上几何等变性。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>单点最致命的假设是：<strong>相机外参标定与末端位姿读数足够准，使得 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">e</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">b</span><span class="mord mathnormal mtight">e</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose"><span class="mclose">)</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">1</span></span></span></span></span></span></span></span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">c</span><span class="mord mathnormal mtight">b</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span></span></span></span></span></span></span></span> 这个变换本身不引入误差。</strong></p><p>整条 3D 通路都建立在它上面。等变性、anchor token 的语义（「原点就是末端」）、乃至视角鲁棒性这一头条卖点，全部依赖于这个坐标变换是精确的。一旦外参有几厘米或几度的偏差，anchor token 取到的就不是末端所在处的几何，而是偏了一段距离的某处——而模型没有任何机制能察觉或补偿这一点，因为它从未见过「原点不是末端」的样本。</p><p>这在实践中很容易不成立。RGB-D 相机的深度本身有噪声（论文自己在 §3.3 开篇就承认「原始深度图存在固有噪声」，并以此作为设计 PEN 的动机）；机械臂长时间运行后标定会漂移；换场景时重新标定通常做得很粗。更微妙的是，<strong>视角变化实验恰恰是对标定精度要求最高的场景</strong>——相机被转到 45°，若新位姿的外参不是重新精确标定的，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">e</span></span></span></span></span></span></span></span></span></span></span> 会整体畸变。论文给出的证据是 GeoVLA 在 45° 下仍有 70%，但没有报告这些新视角的外参是如何获得的，也没有做任何外参扰动实验。这是全文最大的证据缺口：一个专门主张视角不变性的方法，却没有对「视角信息来源」本身的可靠性做敏感性分析。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做、只需 LIBERO：</p><ul><li><strong>数据/环境</strong>：LIBERO-Spatial 与 LIBERO-90，用仿真渲染的深度（真值，无噪声）。</li><li><strong>实现</strong>：复用作者的 PEN + 3DAE 配方训一个模型；推理时对外参施加受控扰动——平移 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">2</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">5</span><span class="mclose">}</span></span></span></span> cm、旋转 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">3</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">5</span><span class="mclose">}</span></span></span></span> 度，以及深度图加 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5782em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">5</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">10</span><span class="mclose">}</span></span></span></span> mm 的高斯噪声。</li><li><strong>测量</strong>：成功率随扰动幅度的衰减曲线，并与 2D 基线（同一 VLM、去掉点云分支）对照。</li><li><strong>判据</strong>：若 GeoVLA 在 2cm/3° 量级扰动下就跌回 2D 基线水平，说明其增益高度依赖精确标定，「几何感知」在真实部署中的可迁移性要打折；若在 5cm/5° 下仍显著领先，则等变性论证站得住，同时也解释了真机上的稳健表现。这个实验成本极低而信息量极大，论文却完全没做。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>对「增益来自 3D 几何理解」最有力的替代解释是：<strong>增益主要来自 anchor token 隐含地把「末端执行器当前位置」这一本体感受信息送进了动作头，而 2D 基线没有这个输入。</strong></p><p>理由很硬：论文明说 LIBERO 上 GeoVLA「只用一路主相机加对应深度，不引入任何额外输入（例如位姿状态或腕部图像）」。但把点云变换到末端坐标系这一步，<strong>必然使用了末端位姿 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">b</span><span class="mord mathnormal mtight">e</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span></strong>。也就是说，本体感受信息其实通过坐标系选择这条侧信道进入了模型，而被比较的 CogACT/OpenVLA 等 2D 基线并没有。表 4 里 π₀ 的括注是「不含位姿状态与其他图像」，进一步说明基线确实被剥夺了这项输入。</p><p>判决实验有两个 arm：（a）给 2D 基线补上末端位姿作为额外条件 token，其余不变；（b）把 GeoVLA 的点云保持在<strong>相机坐标系</strong>、不做末端变换，但另外把末端位姿作为显式 token 输入。若（a）就能吃掉大部分差距，则「几何」的贡献被高估；若（b）明显差于原版而（a）不行，才说明关键在于<strong>坐标系对齐</strong>而非单纯多了一个位姿输入。</p><p>另一个可预测的失败场景由表 8 直接给出：撤掉海绵垫后 GeoVLA 掉到 50，低于 π₀ 的 60。这是唯一一个「目标物体绝对高度改变、但相对末端的几何仍需重新推理」的变化，而它恰恰是 GeoVLA 表现最差的一项。合理的解释是：末端坐标系抹掉的是<strong>当前末端位姿</strong>，因此策略难以利用「桌面在世界系中的绝对高度」这类信息——可以预期在需要绝对高度先验的任务（例如恒定高度的传送带、固定台面）上，该设计是负作用。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：GeoVLA 把整片点云压成<strong>一个</strong> token，且坐标系被硬绑定在末端执行器上。这在单臂、单接触点、准静态任务上足够，但它同时抹掉了两类信息——多接触点的几何（双臂、灵巧手、工具尖端各自需要自己的参照系）与场景的绝对结构（桌面高度、容器内壁）。</p><p><strong>新 framing</strong>：不要选一个坐标系，而是让模型学一组<strong>任务条件的参照系</strong>。具体说，把 PEN 从「固定原点 + 单 anchor」推广为「由语言与视觉共同预测出的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 个查询点（末端、目标物体质心、容器口沿等），每个查询点各生成一个以自身为原点的局部几何 token」。这不是加模块，而是把 §6 里的等变性论证从「对末端等变」推广到「对每个语义相关部位分别等变」，从而让同一套机制自然覆盖双臂与灵巧手——每只手、每根手指都可以是一个原点。</p><p><strong>可借鉴的相邻工具</strong>：开放词表检测/指代分割里的可学习查询（DETR 式 object query），以及等变网络中「按局部坐标架构造特征」的做法（局部标架 / frame averaging）。前者提供「查询点从哪来」，后者提供「多个局部标架如何一致地聚合」。</p><p><strong>第一个实验</strong>：在最能暴露单参照系局限的场景上做——把 GeoVLA 原样搬到双臂平台（例如 RoboTwin 2.0 或 PerAct2 一类双臂任务），比较（i）单一末端 anchor（左手或右手二选一）、（ii）双 anchor（左右末端各一个）、（iii）双 anchor + 一个由语言预测的目标物体 anchor。若（ii）相对（i）有大幅提升、（iii）再有增益，就说明「参照系数量」而非「点云容量」才是当前设计的真实瓶颈；若（ii）≈（i），则说明单 token 瓶颈本身已经足够，反而支持把研究重点放回标定鲁棒性（§9）。</p>',55)])])}const d=a(l,[["render",e]]);export{o as __pageData,d as default};
